    sample_array = [64, 34, 25, 12, 22, 11, 90]
    print("Original List:", sample_array)
    print("Sorted List using Binary Search:", binary_search(sample_array, 34))
    print("Sorted List using Insertion Sort:", insertion_sort(sample_array))
    print("Sorted List using Selection Sort:", selection_sort(sample_array))
    print("Sorted List using Bubble Sort:", bubble_sort(sample_array))
